2523: # ----------------------------------------------------------------------------- effort vocabularies
2524: #
2525: # -Effort and the purpose presets speak low|medium|high|xhigh. What an endpoint accepts
2526: # is DECLARED, never inferred (no host-wide or model-prefix guess): capability table
2527: # caps-v1 -
2528: #   the built-in openai provider (no user table, no OPENAI_BASE_URL)
2529: #       vocabulary openai for any model (Codex validates its own models)   low medium high xhigh
2530: #   hosts api.z.ai, open.bigmodel.cn
2531: #       vocabulary zai (mapping zai-v1) ONLY for the declared models below  low high max
2532: #       (exact, case-sensitive): medium -> high, xhigh -> max
2533: #   hosts token-plan-ams.xiaomimimo.com, token-plan-cn.xiaomimimo.com, api.xiaomimimo.com
2534: #       vocabulary mimo (mapping mimo-v1) ONLY for the declared models     none low medium
2535: #       below (exact): low, medium, high as is, xhigh -> high               high
2536: #   engine:agy (the agy engine, any model)
2537: #       vocabulary model-tier (mapping model-tier): NOTHING is sent - the reasoning tier is
2538: #       part of the agy model id (gemini-3.8-flash-high); effort_sent null. -NativeEffort
2539: #       sends --effort <value> verbatim (agy checks it against the tier itself). The reply
2540: #       schema travels natively (--json-schema): SchemaTransport 'native'.
2541: # Anything else - an undeclared model on a known host, any model on another endpoint -
2542: # has no vocabulary: the run is refused unless -NativeEffort sends a value verbatim.
2543: # Codex's events do not report the effort the endpoint applied: effort_confirmed is null.
2544: $script:EffortCapsVersion = 'caps-v1'
2545: $script:EffortVocabularies = @{
2546:     'openai' = @{ Mapping = 'openai'; Map = @{ 'low' = 'low'; 'medium' = 'medium'; 'high' = 'high'; 'xhigh' = 'xhigh' } }
2547:     'zai'    = @{ Mapping = 'zai-v1'; Map = @{ 'low' = 'low'; 'medium' = 'high'; 'high' = 'high'; 'xhigh' = 'max' } }
2548:     'mimo'   = @{ Mapping = 'mimo-v1'; Map = @{ 'low' = 'low'; 'medium' = 'medium'; 'high' = 'high'; 'xhigh' = 'high' } }
2549:     # BytePlus ModelArk Coding Plan (the Codex integration doc: model_reasoning_effort = low | medium | high)
2550:     'ark'    = @{ Mapping = 'ark-v1'; Map = @{ 'low' = 'low'; 'medium' = 'medium'; 'high' = 'high'; 'xhigh' = 'high' } }
2551:     # Kimi Code (Moonshot) on its Codex base URL: K3 takes low | high | max (the Kimi Code Codex doc)
